//! User-selectable app icon (Settings › Theme › App icon).
//!
//! The artwork is embedded at compile time from `icons/alt/`, generated by
//! `brand/make-alt-icons.py` from the same 1024 masters the iOS picker uses.
//!
//! This only repaints the **running** app: macOS reads the Finder/Launchpad icon
//! out of the `.app` bundle, which a running process cannot rewrite. So the choice
//! lives in the frontend (localStorage) and is re-applied on every launch — see
//! `applyStoredAppIcon` in ui/web/src/lib/appIcon.js.

#[cfg(not(target_os = "macos"))]
use tauri::Manager;

/// Every selectable icon. Keep the keys in step with `APP_ICONS` in
/// ui/web/src/lib/appIcon.js and with `AppIconOption` on iOS.
const ICONS: &[(&str, &[u8])] = &[
    ("classic", include_bytes!("../icons/alt/classic.png")),
    ("sun", include_bytes!("../icons/alt/sun.png")),
    ("vennlight", include_bytes!("../icons/alt/vennlight.png")),
    ("graffiti", include_bytes!("../icons/alt/graffiti.png")),
    ("groovebox", include_bytes!("../icons/alt/groovebox.png")),
];

fn artwork(name: &str) -> Option<&'static [u8]> {
    ICONS.iter().find(|(k, _)| *k == name).map(|(_, png)| *png)
}

/// Repaint the running app's icon. `name` must be one of `ICONS`.
///
/// In a dev run this also overwrites the golden DEV Dock badge that `setup`
/// applies — the badge is back on the next launch, before the stored choice is
/// re-applied.
#[tauri::command]
pub fn set_app_icon(app: tauri::AppHandle, name: String) -> Result<(), String> {
    let png = artwork(&name).ok_or_else(|| format!("unknown app icon: {name}"))?;

    #[cfg(target_os = "macos")]
    {
        let _ = &app;
        // AppKit is main-thread-only and the command arrives on a worker thread.
        app.run_on_main_thread(move || set_dock_icon(png))
            .map_err(|e| e.to_string())
    }

    // Windows/Linux have no Dock; the taskbar reads the window icon instead.
    #[cfg(not(target_os = "macos"))]
    {
        let image = tauri::image::Image::from_bytes(png).map_err(|e| e.to_string())?;
        for window in app.webview_windows().values() {
            window.set_icon(image.clone()).map_err(|e| e.to_string())?;
        }
        Ok(())
    }
}

/// macOS: swap the running app's Dock icon. Must be called on the main thread.
#[cfg(target_os = "macos")]
pub fn set_dock_icon(png: &[u8]) {
    use objc::runtime::Object;
    use objc::{class, msg_send, sel, sel_impl};

    unsafe {
        let data: *mut Object = msg_send![class!(NSData),
            dataWithBytes: png.as_ptr() as *const std::ffi::c_void
            length: png.len()];
        if data.is_null() {
            return;
        }
        let image: *mut Object = msg_send![class!(NSImage), alloc];
        let image: *mut Object = msg_send![image, initWithData: data];
        if image.is_null() {
            return;
        }
        let ns_app: *mut Object = msg_send![class!(NSApplication), sharedApplication];
        let _: () = msg_send![ns_app, setApplicationIconImage: image];
    }
}
